def is_stuck(events, now, grace):
    # Parse events into a dictionary: {job_id: [event_at, state]} for latest state
    job_states = {}
    for event in events:
        job_id, state, event_at = event.split(' at=')[0].split(' job=')[1], event.split(' at=')[1].split(';')[0], int(event.split(' at=')[1].split(';')[0])
        if job_id not in job_states:
            job_states[job_id] = {'state': state, 'event_at': event_at}
        else:
            # Update only if the new event is more recent
            if event_at > job_states[job_id]['event_at']:
                job_states[job_id]['state'] = state
                job_states[job_id]['event_at'] = event_at

    # Collect stuck jobs: running state and event_at older than grace
    stuck_jobs = []
    for job_id, data in job_states.items():
        if data['state'] == 'running' and data['event_at'] < now - grace:
            stuck_jobs.append(job_id)

    # Return sorted list of stuck job IDs
    return sorted(stuck_jobs)
